const root = ReactDOM.createRoot(document.querySelector('#root'));

const courses = [
  { title: '자바스크립트 입문', hours: 12 },
  { title: '리액트 시작하기', hours: 20 },
  { title: 'CSS 레이아웃 마스터', hours: 8 },
];

const Course = ({ title, hours }) => (
  <article className="course">
    <h3 className="course__title">{title}</h3>
    <p className="course__meta">{hours}시간</p>
  </article>
);

root.render(
  <div className="grid">
    {courses.map((course) => (
      <Course title={course.title} hours={course.hours} />
    ))}
  </div>
);

